.heart { transition: scale .45s linear(0, 1.3 30%, .9 55%, 1.04 78%, 1); }
.knob { transition: translate .4s cubic-bezier(.34, 1.56, .64, 1); }
.tick { stroke-dasharray: 42px; stroke-dashoffset: 42px;
  transition: stroke-dashoffset .4s cubic-bezier(.65, 0, .35, 1); }
.done .tick { stroke-dashoffset: 0; }
